Object.assign(SNIP,{"l37kc": "class ThietBi { protected: string ma; ... };\nclass MayIn   : virtual public ThietBi { ... };   // virtual: \"nếu gặp ThietBi ở nhánh khác thì dùng chung\"\nclass MayQuet : virtual public ThietBi { ... };\nclass MayDaNang : public MayIn, public MayQuet {\npublic:\n    MayDaNang(string m) : ThietBi(m), MayIn(m), MayQuet(m) {}   // lớp cuối cùng tự dựng ThietBi\n};", "l37syn": "class CoTen {                                  // giao diện 1\npublic:\n    virtual string ten() const = 0;\n    virtual ~CoTen() {}\n};\nclass CoGia {                                  // giao diện 2\npublic:\n    virtual long long gia() const = 0;\n    virtual ~CoGia() {}\n};\n\nclass SanPham : public CoTen, public CoGia {   // hai lớp cha, mỗi lớp ghi public riêng\n    string t;\n    long long g;\npublic:\n    SanPham(string a, long long b) : t(a), g(b) {}\n    string ten() const override { return t; }\n    long long gia() const override { return g; }\n};"});PRESET_NOTES["l37"]={"Ví dụ: Một lớp, hai lớp cha": "Tạo theo thứ tự khai báo lớp cha (A rồi B), rồi tới C; hủy ngược lại. x có đủ a, b, c. sizeof(C) = 24: a ở +0, b (double, cần chia hết cho 8) ở +8, c ở +16, làm tròn lên bội của 8.", "Ví dụ: Con trỏ tới lớp cha thứ hai": "pa trùng địa chỉ x vì phần A nằm ở đầu. pb lớn hơn 8 byte: trình biên dịch tự cộng độ lệch để pb chỉ đúng vào phần B. Trong Hình động, mũi tên của pb chỉ vào khung “phần B” ở giữa đối tượng.", "Ví dụ: Ghép hai giao diện": "inTen chỉ cần một CoTen, inGia chỉ cần một CoGia; s đáp ứng cả hai. Đối tượng có HAI vptr: một ở đầu (phần CoTen, dùng chung với SanPham), một ở phần CoGia. sizeof = 8 + 8 (hai vptr) + 32 (string) + 8 = 56.", "Lỗi: Tên trùng giữa hai lớp cha": "C có hai hàm chao (của A và của B), g++ không tự chọn: request for member 'chao' is ambiguous. Sửa bằng c.A::chao(), hoặc viết chao() trong C (xem ví dụ kế tiếp).", "Ví dụ: Gỡ mơ hồ bằng tên lớp cha": "C viết lại chao() nên c.chao() không còn mơ hồ; bên trong, A::chao() và B::chao() gọi đúng bản của từng lớp cha. Từ bên ngoài vẫn gọi riêng được một bản: c.B::chao().", "Lỗi: Kim cương không có virtual": "MayDaNang chứa hai phần ThietBi (qua MayIn và qua MayQuet), nên có hai biến ma: m.ma không biết lấy cái nào, g++ báo request for member 'ma' is ambiguous. Xóa dòng đó thì sizeof(MayDaNang) = 64, gấp đôi ThietBi: đúng là có hai bản.", "Ví dụ: Kế thừa ảo": "Chỉ có MỘT phần ThietBi, và chính MayDaNang dựng nó (ThietBi(\"MDN\")), trước cả MayIn và MayQuet. Các lời gọi ThietBi(m + \"-in\") và ThietBi(m + \"-quet\") bị bỏ qua. Vì vậy in và quet cùng thấy ma = \"MDN\", và ThietBi* p = &m không còn mơ hồ.", "Lỗi: Viết danh sách khởi tạo sai thứ tự": "Danh sách viết c, B, A nhưng thứ tự thật luôn là A, B (theo thứ tự khai báo lớp cha) rồi c. Chương trình vẫn chạy, nhưng g++ cảnh báo -Wreorder hai lần (c trước B, B trước A). Viết đúng thứ tự: C() : A(1), B(2), c(3)."};EX_HINTS["l37"]=[["Hàm tạo DongHoBaoThuc(g, p, ag, ap) gọi cả hai hàm tạo lớp cha: : DongHo(g, p), ChuongBao(ag, ap).", "Trong chay, dùng được gio, phut (của DongHo) và hg, hp (của ChuongBao) vì chúng là protected."], ["SanPham* s = new SanPham(t, g); rồi push_back(s) vào cả ba vector: C++ tự đổi SanPham* sang CoTen* và CoGia*.", "Chỉ delete một lần cho mỗi sản phẩm (qua vector kho), đừng delete thêm qua theoTen hay theoGia."], ["Thêm virtual vào hai dòng kế thừa: class MayIn : virtual public ThietBi, class MayQuet : virtual public ThietBi.", "ThietBi không có hàm tạo mặc định nên MayDaNang phải tự gọi ThietBi(m) trong danh sách khởi tạo, đứng trước MayIn(m), MayQuet(m)."]];
/* ===================== BÀI 37 · Đa kế thừa ===================== */
/* Bài 37 · Đa kế thừa
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P37=[{label:"Ví dụ: Một lớp, hai lớp cha",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass A {\npublic:\n    int a = 1;\n    A() {\n        cout << \"Tao A\\n\";\n    }\n    ~A() {\n        cout << \"Huy A\\n\";\n    }\n};\n\nclass B {\npublic:\n    double b = 2.5;\n    B() {\n        cout << \"Tao B\\n\";\n    }\n    ~B() {\n        cout << \"Huy B\\n\";\n    }\n};\n\nclass C : public A, public B {\npublic:\n    int c = 3;\n    C() {\n        cout << \"Tao C\\n\";\n    }\n    ~C() {\n        cout << \"Huy C\\n\";\n    }\n};\n\nint main() {\n    C x;\n    cout << x.a << \" \" << x.b << \" \" << x.c << \"\\n\";\n    cout << sizeof(A) << \" \" << sizeof(B) << \" \" << sizeof(C) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Con trỏ tới lớp cha thứ hai",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass A {\npublic:\n    int a = 1;\n};\n\nclass B {\npublic:\n    double b = 2.5;\n};\n\nclass C : public A, public B {\npublic:\n    int c = 3;\n};\n\nint main() {\n    C x;\n    A* pa = &x;\n    B* pb = &x;\n    cout << \"&x = \" << &x << \"\\n\";\n    cout << \"pa = \" << pa << \"\\n\";\n    cout << \"pb = \" << pb << \"\\n\";\n    cout << pa->a << \" \" << pb->b << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Ghép hai giao diện",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass CoTen {\npublic:\n    virtual string ten() const = 0;\n    virtual ~CoTen() {}\n};\n\nclass CoGia {\npublic:\n    virtual long long gia() const = 0;\n    virtual ~CoGia() {}\n};\n\nclass SanPham : public CoTen, public CoGia {\n    string t;\n    long long g;\npublic:\n    SanPham(string a, long long b) : t(a), g(b) {}\n    string ten() const override {\n        return t;\n    }\n    long long gia() const override {\n        return g;\n    }\n};\n\nvoid inTen(const CoTen& x) {\n    cout << \"Ten: \" << x.ten() << \"\\n\";\n}\n\nvoid inGia(const CoGia& x) {\n    cout << \"Gia: \" << x.gia() << \"\\n\";\n}\n\nint main() {\n    SanPham s(\"But bi\", 5000);\n    inTen(s);\n    inGia(s);\n    CoGia* p = new SanPham(\"Vo\", 12000);\n    cout << p->gia() << \"\\n\";\n    delete p;\n    cout << sizeof(SanPham) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: Tên trùng giữa hai lớp cha",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass A {\npublic:\n    void chao() const {\n        cout << \"A chao\\n\";\n    }\n};\n\nclass B {\npublic:\n    void chao() const {\n        cout << \"B chao\\n\";\n    }\n};\n\nclass C : public A, public B {\n};\n\nint main() {\n    C c;\n    c.chao();\n    return 0;\n}"},{label:"Ví dụ: Gỡ mơ hồ bằng tên lớp cha",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass A {\npublic:\n    void chao() const {\n        cout << \"A chao\\n\";\n    }\n};\n\nclass B {\npublic:\n    void chao() const {\n        cout << \"B chao\\n\";\n    }\n};\n\nclass C : public A, public B {\npublic:\n    void chao() const {\n        A::chao();\n        B::chao();\n        cout << \"C chao\\n\";\n    }\n};\n\nint main() {\n    C c;\n    c.chao();\n    c.B::chao();\n    return 0;\n}"},{label:"Lỗi: Kim cương không có virtual",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass ThietBi {\npublic:\n    string ma = \"TB\";\n};\n\nclass MayIn : public ThietBi {\n};\n\nclass MayQuet : public ThietBi {\n};\n\nclass MayDaNang : public MayIn, public MayQuet {\n};\n\nint main() {\n    MayDaNang m;\n    cout << sizeof(ThietBi) << \" \" << sizeof(MayDaNang) << \"\\n\";\n    cout << m.ma << \"\\n\";\n    return 0;\n}"},{label:"Ví dụ: Kế thừa ảo",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass ThietBi {\nprotected:\n    string ma;\npublic:\n    ThietBi(string m) : ma(m) {\n        cout << \"Tao ThietBi \" << m << \"\\n\";\n    }\n    virtual void moTa() const {\n        cout << \"Thiet bi \" << ma << \"\\n\";\n    }\n    virtual ~ThietBi() {}\n};\n\nclass MayIn : virtual public ThietBi {\npublic:\n    MayIn(string m) : ThietBi(m + \"-in\") {\n        cout << \"Tao MayIn\\n\";\n    }\n    void in() const {\n        cout << ma << \" in\\n\";\n    }\n};\n\nclass MayQuet : virtual public ThietBi {\npublic:\n    MayQuet(string m) : ThietBi(m + \"-quet\") {\n        cout << \"Tao MayQuet\\n\";\n    }\n    void quet() const {\n        cout << ma << \" quet\\n\";\n    }\n};\n\nclass MayDaNang : public MayIn, public MayQuet {\npublic:\n    MayDaNang(string m) : ThietBi(m), MayIn(m), MayQuet(m) {\n        cout << \"Tao MayDaNang\\n\";\n    }\n    void moTa() const override {\n        cout << \"May da nang \" << ma << \"\\n\";\n    }\n};\n\nint main() {\n    MayDaNang m(\"MDN\");\n    m.in();\n    m.quet();\n    ThietBi* p = &m;\n    p->moTa();\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: Viết danh sách khởi tạo sai thứ tự",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass A {\npublic:\n    A(int x) {\n        cout << \"A \" << x << \"\\n\";\n    }\n};\n\nclass B {\npublic:\n    B(int x) {\n        cout << \"B \" << x << \"\\n\";\n    }\n};\n\nclass C : public A, public B {\n    int c;\npublic:\n    C() : c(3), B(2), A(1) {\n        cout << \"C \" << c << \"\\n\";\n    }\n};\n\nint main() {\n    C x;\n    return 0;\n}"}];
const sim37=makeSim2(document.getElementById("sim-l37"),{id:"s37",presets:P37});
makeEx2(document.getElementById("ex-l37"),sim37,[{t:"Đồng hồ báo thức",d:"Lớp <code>DongHo<\/code> giữ giờ, phút (có <code>tang1()<\/code> tăng một phút, sau 23:59 là 00:00, và <code>hien()<\/code> trả về chuỗi <code>HH:MM<\/code>). Lớp <code>ChuongBao<\/code> giữ giờ hẹn. Viết lớp <code>DongHoBaoThuc : public DongHo, public ChuongBao<\/code> có hàm <code>chay(k)<\/code>: tăng k lần, mỗi lần một phút; sau mỗi lần tăng, nếu giờ hiện tại trùng giờ hẹn thì in <code>RENG HH:MM<\/code>. Nhập giờ phút hiện tại, giờ phút hẹn, rồi k (0 ≤ k ≤ 3000). Cuối cùng in <code>Bay gio HH:MM<\/code>.",tests:[{in:"6 58\n7 0\n5",out:"RENG 07:00\nBay gio 07:03"},{in:"23 59\n0 0\n1441",out:"RENG 00:00\nRENG 00:00\nBay gio 00:00"},{in:"10 0\n9 0\n30",out:"Bay gio 10:30"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass DongHo {\nprotected:\n    int gio, phut;\npublic:\n    DongHo(int g, int p) : gio(g), phut(p) {}\n    void tang1() {\n        phut++;\n        if (phut == 60) { phut = 0; gio = (gio + 1) % 24; }\n    }\n    string hien() const {\n        return (gio < 10 ? \"0\" : \"\") + to_string(gio) + \":\" + (phut < 10 ? \"0\" : \"\") + to_string(phut);\n    }\n};\n\nclass ChuongBao {\nprotected:\n    int hg, hp;\npublic:\n    ChuongBao(int g, int p) : hg(g), hp(p) {}\n};\n\n// viết DongHoBaoThuc kế thừa cả DongHo và ChuongBao, có hàm chay(int k)\n\nint main() {\n    int g, p, ag, ap, k;\n    cin >> g >> p >> ag >> ap >> k;\n    // tạo đồng hồ, chạy k phút, in giờ cuối\n    return 0;\n}",need:/class\s+DongHoBaoThuc\s*:\s*public\s+DongHo\s*,\s*public\s+ChuongBao/,needMsg:"Hãy viết class DongHoBaoThuc : public DongHo, public ChuongBao."},{t:"Kho hàng hai giao diện",d:"Hai giao diện có sẵn: <code>CoTen<\/code> (<code>ten()<\/code>) và <code>CoGia<\/code> (<code>gia()<\/code>), cùng hai hàm <code>inDanhSach(const vector&lt;CoTen*&gt;&amp;)<\/code> và <code>tongGia(const vector&lt;CoGia*&gt;&amp;)<\/code>. Viết lớp <code>SanPham<\/code> kế thừa cả hai. Nhập n rồi n dòng <code>ten gia<\/code>; tạo mỗi sản phẩm một lần bằng <code>new<\/code>, cho <b>cùng một con trỏ<\/b> vào cả hai vector (mỗi vector nhìn sản phẩm qua một giao diện). In danh sách tên (do <code>inDanhSach<\/code>), rồi <code>Tong: ...<\/code>, cuối cùng giải phóng bộ nhớ.",tests:[{in:"3\nBut 5000\nVo 12000\nThuoc 3000",out:"1. But\n2. Vo\n3. Thuoc\nTong: 20000"},{in:"1\nSach 1000000000",out:"1. Sach\nTong: 1000000000"},{in:"2\nA 0\nB 7",out:"1. A\n2. B\nTong: 7"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass CoTen {\npublic:\n    virtual string ten() const = 0;\n    virtual ~CoTen() {}\n};\n\nclass CoGia {\npublic:\n    virtual long long gia() const = 0;\n    virtual ~CoGia() {}\n};\n\nvoid inDanhSach(const vector<CoTen*>& ds) {\n    for (int i = 0; i < (int)ds.size(); i++) cout << i + 1 << \". \" << ds[i]->ten() << \"\\n\";\n}\n\nlong long tongGia(const vector<CoGia*>& ds) {\n    long long s = 0;\n    for (CoGia* x : ds) s += x->gia();\n    return s;\n}\n\n// viết SanPham kế thừa public CoTen và public CoGia\n\nint main() {\n    int n;\n    cin >> n;\n    vector<SanPham*> kho;\n    vector<CoTen*> theoTen;\n    vector<CoGia*> theoGia;\n    for (int i = 0; i < n; i++) {\n        string t;\n        long long g;\n        cin >> t >> g;\n        // tạo một SanPham, đưa vào cả ba vector\n    }\n    inDanhSach(theoTen);\n    cout << \"Tong: \" << tongGia(theoGia) << \"\\n\";\n    // delete qua vector kho\n    return 0;\n}",need:/class\s+SanPham\s*:\s*public\s+CoTen\s*,\s*public\s+CoGia/,needMsg:"Hãy viết class SanPham : public CoTen, public CoGia."},{t:"Máy đa năng",d:"Lớp <code>ThietBi<\/code> giữ mã máy và số thao tác đã làm (<code>thaoTac<\/code>). <code>MayIn<\/code> có <code>in(k)<\/code> (cộng k vào số trang in), <code>MayQuet<\/code> có <code>quet(k)<\/code>; mỗi lần gọi <code>in<\/code> hay <code>quet<\/code> đều tăng <code>thaoTac<\/code> thêm 1. Sửa để <code>MayDaNang<\/code> kế thừa cả hai mà <b>chỉ có một<\/b> ThietBi (dùng kế thừa ảo), rồi viết <code>photo(k)<\/code> = quét k trang rồi in k trang. Nhập mã máy, q, rồi q lệnh <code>in k<\/code>, <code>quet k<\/code> hoặc <code>photo k<\/code>. In bốn dòng: mã máy, <code>In: ...<\/code>, <code>Quet: ...<\/code>, <code>Thao tac: ...<\/code>.",tests:[{in:"MDN-01\n4\nin 3\nquet 2\nphoto 5\nin 1",out:"MDN-01\nIn: 9\nQuet: 7\nThao tac: 5"},{in:"X\n0",out:"X\nIn: 0\nQuet: 0\nThao tac: 0"},{in:"AB\n2\nphoto 10\nphoto 1",out:"AB\nIn: 11\nQuet: 11\nThao tac: 4"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass ThietBi {\nprotected:\n    string ma;\n    int thaoTac = 0;\npublic:\n    ThietBi(string m) : ma(m) {}\n};\n\nclass MayIn : public ThietBi {          // sửa: chỉ muốn MỘT ThietBi trong MayDaNang\nprotected:\n    int trangIn = 0;\npublic:\n    MayIn(string m) : ThietBi(m) {}\n    void in(int k) {\n        trangIn += k;\n        thaoTac++;\n    }\n};\n\nclass MayQuet : public ThietBi {        // sửa tương tự\nprotected:\n    int trangQuet = 0;\npublic:\n    MayQuet(string m) : ThietBi(m) {}\n    void quet(int k) {\n        trangQuet += k;\n        thaoTac++;\n    }\n};\n\nclass MayDaNang : public MayIn, public MayQuet {\npublic:\n    MayDaNang(string m) : MayIn(m), MayQuet(m) {}\n    // viết photo(k) và hàm in báo cáo\n};\n\nint main() {\n    string ma;\n    int q;\n    cin >> ma >> q;\n    MayDaNang m(ma);\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        int k;\n        cin >> lenh >> k;\n        // gọi in, quet hoặc photo\n    }\n    // in báo cáo 4 dòng\n    return 0;\n}",need:/class\s+MayIn\s*:\s*virtual\s+public\s+ThietBi[\s\S]*class\s+MayQuet\s*:\s*virtual\s+public\s+ThietBi/,needMsg:"MayIn và MayQuet phải kế thừa ảo: virtual public ThietBi."}]);

makeQuiz("quiz37","score37",[{"q": "<code>class C : public A, public B<\/code> và hàm tạo viết <code>C() : B(), A() {}<\/code>. Hàm tạo nào chạy trước?", "o": ["B, vì được viết trước trong danh sách", "A, vì A được khai báo trước sau dấu :", "Ngẫu nhiên", "C"], "a": 1, "e": "Lớp cha được dựng theo thứ tự khai báo sau dấu :, không theo danh sách khởi tạo (g++ cảnh báo -Wreorder)."}, {"q": "A và B đều có hàm <code>f()<\/code>, <code>C : public A, public B<\/code> không viết f. <code>c.f()<\/code> thì sao?", "o": ["Gọi A::f vì A đứng trước", "Gọi B::f vì B đứng sau", "Lỗi biên dịch: tên f mơ hồ", "Gọi cả hai"], "a": 2, "e": "Trình biên dịch không tự chọn; phải ghi c.A::f() hoặc viết f trong C."}, {"q": "Kim cương <b>không<\/b> dùng virtual: B : A, C : A, D : B, C. Một đối tượng D chứa bao nhiêu phần A?", "o": ["0", "1", "2", "3"], "a": 2, "e": "Mỗi nhánh mang theo một phần A riêng, nên có hai bản."}, {"q": "Với kế thừa ảo (B, C đều <code>virtual public A<\/code>, D : B, C), khi tạo một D thì ai gọi hàm tạo của A?", "o": ["B", "C", "Cả B và C", "D, lớp con cuối cùng"], "a": 3, "e": "Lớp cơ sở ảo được dựng đúng một lần bởi lớp con cuối cùng, trước các lớp cha khác."}]);

